/**
 * One-Stop Flight Search Simulator
 * Generates sample flight data and finds all one-stop routes
 * between a given origin and destination.
 */

const fs = require("fs");
const path = require("path");

// ── Sample Data ──────────────────────────────────────────────
const AIRLINES = ["SkyWay Air", "Global Wings", "Pacific Express", "Atlantic Jet", "Star Alliance Air"];
const AIRPORTS = {
  JFK: "New York (JFK)",
  LAX: "Los Angeles (LAX)",
  ORD: "Chicago O'Hare (ORD)",
  DFW: "Dallas/Fort Worth (DFW)",
  DEN: "Denver (DEN)",
  ATL: "Atlanta (ATL)",
  SFO: "San Francisco (SFO)",
  SEA: "Seattle (SEA)",
  MIA: "Miami (MIA)",
  BOS: "Boston (BOS)",
};

// Simple seeded random
let seed = 42;
function rand() {
  seed = (seed * 16807 + 0) % 2147483647;
  return (seed - 1) / 2147483646;
}
function randInt(min, max) {
  return Math.floor(rand() * (max - min + 1)) + min;
}
function randChoice(arr) {
  return arr[Math.floor(rand() * arr.length)];
}

// ── Helper: date math ────────────────────────────────────────
function addMinutes(dateStr, mins) {
  const d = new Date(dateStr);
  d.setMinutes(d.getMinutes() + mins);
  return fmt(d);
}
function fmt(d) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
function diffMin(a, b) {
  return (new Date(b) - new Date(a)) / 60000;
}

// ── Generate Flights ─────────────────────────────────────────
function generateFlights(dateStr = "2025-08-15") {
  const flights = [];
  let id = 1000;
  const codes = Object.keys(AIRPORTS);

  for (const origin of codes) {
    for (const dest of codes) {
      if (origin === dest) continue;
      if (rand() > 0.4) continue;

      const numFlights = randInt(1, 2);
      for (let n = 0; n < numFlights; n++) {
        const depHour = randInt(5, 21);
        const depMin = randChoice([0, 15, 30, 45]);
        const durationMin = randInt(90, 330);
        const departure = `${dateStr} ${String(depHour).padStart(2, "0")}:${String(depMin).padStart(2, "0")}`;
        const arrival = addMinutes(departure, durationMin);
        const price = Math.round((rand() * 361 + 89) * 100) / 100;

        flights.push({
          flight_id: `FL${id++}`,
          airline: randChoice(AIRLINES),
          origin,
          destination: dest,
          departure,
          arrival,
          duration_min: durationMin,
          price_usd: price,
        });
      }
    }
  }
  return flights;
}

// ── Find One-Stop Routes ─────────────────────────────────────
function findOneStopRoutes(flights, origin, destination, minLayover = 45, maxLayover = 300) {
  const byOrigin = {};
  for (const f of flights) {
    (byOrigin[f.origin] ||= []).push(f);
  }

  const results = [];

  for (const leg1 of byOrigin[origin] || []) {
    const stopover = leg1.destination;
    if (stopover === destination || stopover === origin) continue;

    for (const leg2 of byOrigin[stopover] || []) {
      if (leg2.destination !== destination) continue;

      const layover = diffMin(leg1.arrival, leg2.departure);
      if (layover < minLayover || layover > maxLayover) continue;

      results.push({
        leg1,
        stopover: AIRPORTS[stopover],
        layover_min: Math.round(layover),
        leg2,
        total_price_usd: Math.round((leg1.price_usd + leg2.price_usd) * 100) / 100,
        total_travel_min: leg1.duration_min + Math.round(layover) + leg2.duration_min,
      });
    }
  }

  results.sort((a, b) => a.total_price_usd - b.total_price_usd);
  return results;
}

// ── Format Report ────────────────────────────────────────────
function formatResults(origin, destination, results) {
  const lines = [];
  const bar = "=".repeat(72);

  lines.push(bar);
  lines.push("  ✈  ONE-STOP FLIGHT SEARCH RESULTS");
  lines.push(bar);
  lines.push(`  Route      : ${AIRPORTS[origin]}  →  ${AIRPORTS[destination]}`);
  lines.push(`  Date       : 2025-08-15`);
  lines.push(`  Results    : ${results.length} itinerary(ies) found`);
  lines.push(bar);

  if (results.length === 0) {
    lines.push("");
    lines.push("  ⚠  No one-stop routes found for this pair. Try different cities.");
    lines.push("");
    return lines.join("\n");
  }

  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    const { leg1: l1, leg2: l2 } = r;
    const layH = Math.floor(r.layover_min / 60);
    const layM = r.layover_min % 60;
    const totH = Math.floor(r.total_travel_min / 60);
    const totM = r.total_travel_min % 60;

    lines.push("");
    lines.push(`  ── Itinerary #${i + 1} ─────────────────────────────────────────`);
    lines.push(`  💰 Total Price : $${r.total_price_usd.toFixed(2).padStart(8)}`);
    lines.push(`  ⏱  Total Travel: ${totH}h ${totM}m (includes layover)`);
    lines.push("");
    lines.push(`  [Leg 1]  ${l1.airline.padEnd(22)}  ${l1.flight_id}`);
    lines.push(`           ${AIRPORTS[l1.origin]}`);
    lines.push(`           Depart : ${l1.departure}   →   Arrive : ${l1.arrival}`);
    lines.push(`           Duration: ${l1.duration_min}min   |   $${l1.price_usd.toFixed(2)}`);
    lines.push("");
    lines.push(`  🔄 Layover at ${r.stopover}  —  ${layH}h ${layM}m`);
    lines.push("");
    lines.push(`  [Leg 2]  ${l2.airline.padEnd(22)}  ${l2.flight_id}`);
    lines.push(`           ${AIRPORTS[l2.origin]}`);
    lines.push(`           Depart : ${l2.departure}   →   Arrive : ${l2.arrival}`);
    lines.push(`           Duration: ${l2.duration_min}min   |   $${l2.price_usd.toFixed(2)}`);
  }

  lines.push("");
  lines.push(bar);
  lines.push("  Sorted by lowest total price. Layover window: 45min – 5hrs.");
  lines.push(bar);
  lines.push("");
  return lines.join("\n");
}

// ── Main ─────────────────────────────────────────────────────
const ORIGIN = "JFK";
const DESTINATION = "LAX";

console.log("Generating sample flight data...");
const flights = generateFlights();
console.log(`  → ${flights.length} direct flight legs generated across ${Object.keys(AIRPORTS).length} airports.\n`);

console.log(`Searching one-stop routes: ${ORIGIN} → ${DESTINATION}...\n`);
const results = findOneStopRoutes(flights, ORIGIN, DESTINATION);

const report = formatResults(ORIGIN, DESTINATION, results);
console.log(report);

// Save results
const dataDir = path.join(__dirname, "..", "data");
fs.mkdirSync(dataDir, { recursive: true });

fs.writeFileSync(path.join(dataDir, "flight_search_results.txt"), report, "utf8");
fs.writeFileSync(
  path.join(dataDir, "flight_search_results.json"),
  JSON.stringify(
    {
      search: { origin: ORIGIN, destination: DESTINATION, date: "2025-08-15", stops: 1 },
      total_legs_generated: flights.length,
      itineraries_found: results.length,
      itineraries: results,
    },
    null,
    2
  ),
  "utf8"
);

console.log("✅ Results saved to:");
console.log("   • /workspace/data/flight_search_results.txt  (readable report)");
console.log("   • /workspace/data/flight_search_results.json (structured data)");
